546	    /**
547	     * SkipListener: 예외 발생 시 로그
548	     */
549	    @Bean
550	    public SkipListener<OrderShipment, OrderShipment> shipmentSkipListener() {
551	        return new SkipListener<>() {
552	            @Override
553	            public void onSkipInProcess(OrderShipment item, Throwable t) {
554	                if (item != null) {
555	                    log.error("[Skip] 배송 상태 처리 스킵: shipmentId={}, trackingNumber={}, status={}, 사유={}",
556	                            item.getId(),
557	                            item.getTrackingNumber(),
558	                            item.getStatus(),
559	                            t.getMessage(),
560	                            t);
561	                } else {
562	                    log.error("[Skip] 배송 상태 처리 스킵: item=null, 사유={}", t.getMessage(), t);
563	                }
564	            }
565	
566	            @Override
567	            public void onSkipInRead(Throwable t) {
568	                log.error("[SkipRead] 배송 정보 읽기 스킵: 사유={}", t.getMessage(), t);
569	            }
570	
571	            @Override
572	            public void onSkipInWrite(OrderShipment item, Throwable t) {
573	                if (item != null) {
574	                    log.error("[SkipWrite] 배송 상태 저장 스킵: shipmentId={}, trackingNumber={}, status={}, 사유={}",
575	                            item.getId(),
576	                            item.getTrackingNumber(),
577	                            item.getStatus(),
578	                            t.getMessage(),
579	                            t);
580	                } else {
581	                    log.error("[SkipWrite] 배송 상태 저장 스킵: item=null, 사유={}", t.getMessage(), t);
582	                }
583	            }
584	        };
585	    }
